"use client";
// The /try form: posts the pasted repo to /api/review and says plainly what came back.
import { useState } from "react";

export type TryState =
  | { kind: "idle" }
  | { kind: "loading" }
  | { kind: "invalid"; message: string }
  | { kind: "rate_limited"; message: string }
  | { kind: "cached"; href: string; label: string }
  | { kind: "queued"; command: string }
  | { kind: "error"; message: string };

/** `owner/repo` from a pasted reference, using the same shapes the API accepts. Null when it is not one. */
export function repoFromInput(input: string): { owner: string; repo: string } | null {
  const raw = input.trim().replace(/\/+$/, "");
  const m = /^(?:https:\/\/github\.com\/)?([A-Za-z0-9][A-Za-z0-9-]*)\/([A-Za-z0-9._-]+?)(?:\.git)?$/.exec(raw);
  return m ? { owner: m[1], repo: m[2] } : null;
}

/** Maps an API status and body to what the page shows. Pure, so each status is testable on its own. */
export function mapResponse(status: number, body: unknown, input: string): TryState {
  const err = typeof (body as { error?: unknown } | null)?.error === "string" ? (body as { error: string }).error : "";
  const ref = repoFromInput(input);
  if (status === 400) return { kind: "invalid", message: err || "That is not a GitHub repository URL." };
  if (status === 429) return { kind: "rate_limited", message: "Try again in a minute" };
  if (status === 200 && (body as { cached?: unknown } | null)?.cached === true && ref) {
    return { kind: "cached", href: `/r/${ref.owner}/${ref.repo}`, label: `${ref.owner}/${ref.repo}` };
  }
  if (status === 202 && ref) {
    return { kind: "queued", command: `bun src/cli.ts review https://github.com/${ref.owner}/${ref.repo} --observational` };
  }
  return { kind: "error", message: "Something went wrong. Nothing was reviewed." };
}

const CONTROL = {
  padding: "10px 12px",
  font: "inherit",
  color: "inherit",
  background: "transparent",
  border: "1px solid var(--line)",
  borderRadius: 6,
} as const;

export function TryForm() {
  const [value, setValue] = useState("");
  const [state, setState] = useState<TryState>({ kind: "idle" });

  async function submit(e: React.FormEvent) {
    e.preventDefault();
    setState({ kind: "loading" });
    try {
      const res = await fetch("/api/review", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ repo: value }),
      });
      const body: unknown = await res.json().catch(() => null);
      setState(mapResponse(res.status, body, value));
    } catch {
      setState({ kind: "error", message: "Could not reach the server. Nothing was reviewed." });
    }
  }

  return (
    <>
      <form onSubmit={submit} style={{ display: "flex", flexWrap: "wrap", gap: 8, margin: "16px 0" }}>
        <label htmlFor="repo" style={{ position: "absolute", left: -9999 }}>GitHub repository URL</label>
        <input
          id="repo"
          type="text"
          inputMode="url"
          autoComplete="off"
          placeholder="https://github.com/owner/repo"
          value={value}
          onChange={(e) => setValue(e.target.value)}
          style={{ ...CONTROL, flex: "1 1 240px", minWidth: 0 }}
        />
        <button type="submit" disabled={state.kind === "loading"} style={{ ...CONTROL, cursor: "pointer" }}>
          {state.kind === "loading" ? "Checking…" : "Review"}
        </button>
      </form>
      <div role="status" aria-live="polite">
        <Result state={state} />
      </div>
    </>
  );
}

function Result({ state }: { state: TryState }) {
  switch (state.kind) {
    case "invalid":
    case "error":
    case "rate_limited":
      return <p className="meta">{state.message}</p>;
    case "cached":
      return (
        <p>
          This repo already has a review: <a href={state.href}>{state.label}</a>
        </p>
      );
    case "queued":
      return (
        <div className="empty" style={{ textAlign: "left" }}>
          <p style={{ marginTop: 0 }}>Not reviewed yet. Run it yourself:</p>
          <pre style={{ overflowX: "auto", whiteSpace: "pre-wrap", wordBreak: "break-all" }}>
            <code>{state.command}</code>
          </pre>
          <p style={{ marginBottom: 0 }}>
            Hosted runs on isolated sandboxes are coming. No review has been started for you.
          </p>
        </div>
      );
    default:
      return null;
  }
}

// T71: the /try form's mapping from API status to page state.
import { describe, expect, test } from "bun:test";
import { mapResponse, repoFromInput } from "../web/components/TryForm.tsx";

const URL_IN = "https://github.com/octo/cat";

describe("mapResponse", () => {
  test("400 shows the API's message", () => {
    expect(mapResponse(400, { error: "not a GitHub repository reference" }, "nope")).toEqual({
      kind: "invalid",
      message: "not a GitHub repository reference",
    });
  });
  test("429 says to try again in a minute", () => {
    expect(mapResponse(429, { error: "too many requests" }, URL_IN)).toEqual({
      kind: "rate_limited",
      message: "Try again in a minute",
    });
  });
  test("200 cached links to the review page", () => {
    expect(mapResponse(200, { cached: true, path: "x" }, `${URL_IN}.git`)).toEqual({
      kind: "cached",
      href: "/r/octo/cat",
      label: "octo/cat",
    });
  });
  test("202 queued gives the CLI command and claims no review", () => {
    expect(mapResponse(202, { queued: true }, `${URL_IN}/`)).toEqual({
      kind: "queued",
      command: "bun src/cli.ts review https://github.com/octo/cat --observational",
    });
  });
  test("unexpected statuses are an error, never a review", () => {
    expect(mapResponse(500, null, URL_IN).kind).toBe("error");
    expect(mapResponse(200, {}, URL_IN).kind).toBe("error");
  });
});

describe("repoFromInput", () => {
  test("accepts URL and bare forms, rejects others", () => {
    expect(repoFromInput("octo/cat")).toEqual({ owner: "octo", repo: "cat" });
    expect(repoFromInput("https://gitlab.com/octo/cat")).toBeNull();
  });
});

